package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamRhythmCreativeBank2 {
    private const val T = "නර්තනයේ රිද්මය, තාල ශාස්ත්‍රය, නව නිර්මාණ හා වෘත්තීය අගය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("දේශීය තාල ශාස්ත්‍රයේදී මාත්‍රා 2, 3, 4, 5, 7 යන ප්‍රමාණයන් හඳුන්වනු ලබන්නේ කුමන නාම පන්තියක් යටතේද?", "ගැළ හෙවත් තිත් ගණන්", "නව රස", "අභිනය වර්ග", "සන්නි වර්ග", "දෙතිත, තුන්තිත, සිව්තිත ආදී ලෙස මාත්‍රා සංඛ්‍යාව අනුව සිංහල තාල වර්ග කෙරේ."),
        q("තාලයක ආරම්භක පළමු මාත්‍රාවට තාලම්පට ගැසීමේදී එම ස්ථානය හඳුන්වන 'තීත්' ගණන කුමක්ද?", "සම් හෙවත් මුල් තිත", "අවසන් හිස් ස්ථානය", "විලම්බ විරාමය", "ඛාලි ස්ථානය", "වැඩිම බර හා අවධාරණය ලැබෙන පළමු මාත්‍රාවෙන් සමස්ත තාල වටයම ආරම්භ වේ."),
        q("වන්නමක හෝ නර්තන අංගයකදී 'අඩව්වක්' කස්තිරමකින් අවසන් කිරීමේදී පවත්වා ගත යුතු ප්‍රධාන නියමය කුමක්ද?", "අවසන් බෙර පදය තාලයේ මුල් තිතට හෙවත් සමට හරියටම වැටීම", "ඕනෑම මොහොතක නතර කිරීම", "බෙර වාදකයාට පසුව අඩිය තැබීම", "වේදිකාවෙන් ඉවතට දුව යාම", "නැට්ටුවා හා වාදකයා එකම අවසන් තිතට පැමිණීමෙන් පද අවසානයේ විශිෂ්ටත්වය දිස්වේ."),
        q("පහතරට නර්තනයේදී බහුලව භාවිත වන 'වට්ටම්' යන පද කොටස්වලින් සිදුවන්නේ කුමක්ද?", "එක් තාලයක් තුළ කාල ලය වැඩි කරමින් වේගවත් නර්තන රටා ගොඩනැගීම", "ශාන්තිකර්මය අවසන් කිරීමේදී වෙස්මුහුණු පිළිවෙළට ගැලවීම", "පෙළපාලි නර්තනය අතරතුර කවි ගායනය සම්පූර්ණයෙන් නතර කිරීම", "මඩුව අවසානයේ පහන් පැලේ දැල්වෙන පන්දම් නිවා දැමීම", "දෙවොල් හා තෙල්මේ නැටුම්වලදී පළමු වට්ටමේ සිට පස්වන හෝ හත්වන වට්ටම දක්වා වේගය ක්‍රමයෙන් වැඩි වේ."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ ආවේණික ලක්ෂණයක් වන 'දිගු තාල ලය' පවත්වා ගැනීමට උපකාරී වන ප්‍රධාන බෙරය කුමක්ද?", "සබරගමු දවුල", "තබ්ලාව", "මෘදංගය", "උඩැක්කිය", "සබරගමු දිගු දවුලේ ගැඹුරු හා අඛණ්ඩ රෝල් නාදය එම නැටුමේ ලයට අනුගත වේ."),
        q("තාලමක මාත්‍රා 6 ක් පවතින විට එය 3 + 3 ලෙස බෙදා වාදනය කිරීම හඳුන්වන්නේ කුමන ආකාරයෙන්ද?", "සම කොටස් දෙකක තුන්තිත යුගලයක් ලෙස", "විෂම පස් මාත්‍රාවක් ලෙස", "සිව්තිත කොටසක් ලෙස", "අට මාත්‍රා වටයක් ලෙස", "තුන්තිත දෙකක් එක්වීමෙන් මාත්‍රා හයේ සුමට චක්‍රයක් නිර්මාණය වේ."),
        q("භාරතීය තාල ශාස්ත්‍රයට අනුව 'ඛාලි' යන්නෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "අත්පුඩි නොගසා අත විවෘතව දිගු කර දක්වන හිස් තාල ස්ථානය", "වැඩිම ශබ්දයකින් තාල ගැසීම", "තාලම්පට බිම තැබීම", "නැටුම සම්පූර්ණයෙන් අවසන් කිරීම", "තාල ආවර්තනයක අඩු බරක් සහිත භාගය හඳුනා ගැනීමට ඛාලිය හෙවත් නිශ්ශබ්ද තාල සංඥාව යොදයි."),
        q("තාල ශාස්ත්‍රයේදී 'තාලි' යන්නෙන් අදහස් කෙරෙන නිවැරදි ක්‍රියාව කුමක්ද?", "අත් දෙක එකට ගසා ශබ්ද නංවා මාත්‍රා ස්ථානය පෙන්වීම", "කටින් ගීත ගැයීම", "පාදයෙන් බිම පෑගීම", "හිස දෙපසට වැනීම", "තාලි මඟින් තාලයක ප්‍රධාන බෙදුම් විභාග ආරම්භ වන ස්ථාන සලකුණු කෙරේ."),
        q("දේශීය හා භාරතීය සම්භාව්‍ය නර්තනයේදී තාලයේ වේගය අඩු කිරීම හෝ වැඩි කිරීම සිදු නොකළ යුතු ප්‍රධාන අවස්ථාව කුමක්ද?", "ස්ථාවර මධ්‍ය ලයෙන් යුත් සරඹ හා පූජා පද අතරතුර", "කස්තිරම් අවසානයේ", "වන්නම් පද සමබර කිරීමේදී", "තනි බෙර වාදන අංගයක", "ශිෂ්‍යයෙකු මූලික තාලය රැක ගැනීමේදී අනපේක්ෂිතව වේගය වැඩි වීම හෝ අඩු වීම තාල දෝෂයකි."),
        q("සිංහල ජන නැටුම්වල 'රබන් පද' හා 'තාල' අතර ඇති සම්බන්ධතාව කුමක්ද?", "රබන් පදවල වචන රටාව ස්වාභාවිකවම නියමිත තාල මාත්‍රාවලට ගැළපී ඇත", "රබන් පදවලට කිසිදු තාලයක් නැත", "රබන් පද වයන්නේ බටනළාවෙන් පමණි", "රබන් පද නැටීමට යොදා නොගනී", "'උඩින් උඩින් වර පෙත්තප්පු' වැනි රබන් පද සිව් මාත්‍රා හෝ සය මාත්‍රා රිද්මයෙන් පිරී ඇත."),
        q("නව නර්තන නිර්මාණයකට සංගීත ඛණ්ඩයක් තෝරා ගැනීමේදී 'නිශ්ශබ්දතාව' (Silence) පවා කලාත්මකව යොදාගත හැක්කේ කෙසේද?", "විස්මය, ශෝකය හෝ ආතතිය ඉස්මතු කිරීමට සුදුසු මොහොතක සංගීතය නතර කර චලන දැක්වීමෙන්", "මුළු නර්තන ප්‍රසංගයම ආරම්භයේ සිට අවසානය දක්වා සංගීතය නොමැතිව පැවැත්වීමෙන්", "බෙර වාදකයාට තාල පදය අමතක වූ අවස්ථාවක ශිල්පීන් වේදිකාව මත නතර වී සිටීමෙන්", "වේදිකාවේ ප්‍රධාන විදුලි පහන් සම්පූර්ණයෙන් නිවා දමා ප්‍රේක්ෂකයා අඳුරේ තැබීමෙන්", "සංගීතය මොහොතකට නතර වන නිහඬතාව තුළ හුස්ම හා චලන ප්‍රේක්ෂක අවධානය තියුණු කරයි."),
        q("සමූහ නර්තනයකදී 'සමකාලීන' (Unison) චලනයක් යන්නෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "සියලුම නර්තන ශිල්පීන් එකම මොහොතේදී එකම ඉරියව්ව හා පියවර සිදු කිරීම", "එක් එක් ශිල්පියා තමන් කැමති වෙනස් වේගයකින් හා රිද්මයකින් වේදිකාවේ නැටීම", "කණ්ඩායමේ ශිල්පීන් පෙළින් පෙළට බිම හිඳගෙන විවිධ හස්ත මුද්‍රා පමණක් දැක්වීම", "පසුබිම් ගායකයන් වේදිකාව ඉදිරියට පැමිණ නැට්ටුවන් වෙනුවට ගීත ගායනා කිරීම", "සමකාලීන චලනය මගින් කණ්ඩායමේ ශක්තිය හා සමගිය එකවර ප්‍රේක්ෂකයාට දැනේ."),
        q("සමූහ නර්තන නිර්මාණකරණයේදී 'කැනන්' (Canon) ක්‍රමය යනු කුමක්ද?", "එකම නර්තන චලනය ශිල්පීන් එකා පසුපස එකා මාත්‍රා කිහිපයක පරතරයකින් සිදු කිරීම", "ගැටබෙරය හා යක් බෙරය පමණක් තනිව වාදනය කිරීම", "නැටුම් අතරතුර ශිල්පීන්ගේ වෙස්මුහුණු එකිනෙකා මාරු කර ගැනීම", "සියලුම නැට්ටුවන් එකවර වේදිකාව මත හිඳගෙන විරාම ගැනීම", "තරංගයක් මෙන් එක් අයෙකුගෙන් පසු තවත් අයෙකු එකම චලනය කිරීමෙන් අලංකාර ප්‍රවාහයක් මැවේ."),
        q("නර්තන නිර්මාණයකදී 'මට්ටම් භාවිතය' (Use of Levels) යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "පහළ (බිම), මධ්‍යම (නැමී) සහ ඉහළ (සිටගෙන හෝ පැන) යන උස මට්ටම් තුනෙහිම චලන යෙදීම", "රංග වේදිකාවේ ලෑලි තට්ටු තුනක් උසට තනා එහි චරිත පෙළගැස්වීම", "බෙර හා තාලම්පට නාදයේ ශබ්ද පරිමාව ක්‍රමයෙන් උස් පහත් කර වාදනය කිරීම", "නරඹන්නන් සඳහා ප්‍රේක්ෂකාගාරයේ ආසන පේළි විවිධ උස මට්ටම්වලින් සැකසීම", "විවිධ උස මට්ටම් භාවිතය නිර්මාණයේ ඒකාකාරී බව නැති කර ත්‍රිමාණ ගැඹුරක් එක් කරයි."),
        q("පහළ මට්ටමේ නර්තන ඉරියව්වක් සඳහා වඩාත් ගැළපෙන නාටකීය භාවයක් කුමක්ද?", "පරාජය, දුක, වන්දනාව හෝ භූමියට ඇති සමීපත්වය", "අහසේ පියාඹන පක්ෂීන්", "උඩඟු ජයග්‍රහණය", "සඳ මුදුනට නැගීම", "ශරීරය බිමට සමීප වන ඉරියව් යටහත් බව, වේදනාව හෝ ගස්වැල් පැළවීම වැනි තේමාවන්ට උචිතය."),
        q("ඉහළ මට්ටමේ උඩ පැනීම් හා එසවීම් මඟින් නර්තනයේදී බහුලව ප්‍රකාශ වන්නේ කුමන හැඟීම්ද?", "ජයග්‍රහණය, උද්‍යෝගය, නිදහස හා වීරත්වය", "අසරණ බව හා නින්ද", "ලෙඩ රෝග", "අලස බව", "උස් මට්ටම් චලන ප්‍රේක්ෂකයා තුළ ශක්තිය හා ප්‍රීතිමත් උද්දාමයක් ඇති කරයි."),
        q("නව නිර්මාණාත්මක නර්තනයකදී 'චලන ප්‍රතිවිරෝධතාව' (Contrast) ඇති කිරීමට යොදාගත හැකි උපක්‍රමය කුමක්ද?", "වේගවත් චලන සමඟ මන්දගාමී චලන හෝ තියුණු චලන සමඟ සුමට චලන ගැළපීම", "සියලු චලන එකම වේගයෙන් තැබීම", "එකම චලනය විනාඩි දහයක් කිරීම", "ආලෝකය නොවෙනස්ව තැබීම", "ප්‍රතිවිරුද්ධ ලක්ෂණ එකට හමුවීමෙන් නර්තනයේ රසය හා ආකර්ෂණය දෙගුණ වේ."),
        q("නර්තන නිර්මාණ ශිල්පියෙකු තේමාවක් ලෙස 'සොබාදහම ආරක්ෂා කිරීම' තෝරාගත් විට වඩාත් උචිත සෞන්දර්ය උපක්‍රමය කුමක්ද?", "ගස්වැල්, ජලය, සතුන් හා මිනිසා අතර බැඳීම සංකේතවත් කරන චලන හා පරිසර හිතකාමී රංග වස්ත්‍ර භාවිතය", "සාම්ප්‍රදායික වන්නම් පද සම්පූර්ණයෙන් ඉවත් කර යුද සටන් පියවර පමණක් යෙදීම", "වේදිකාව පුරා අඳුරු තිර ඇද කිසිදු නර්තන චලනයක් නොපෙන්වා දෙබස් කීම", "වේගවත් කස්තිරම් මඟින් හාස්‍යජනක කෝලම් රංගනයක් පමණක් ඉදිරිපත් කිරීම", "නර්තනය සමාජ පණිවිඩයක් සංවේදී කලා මාධ්‍යයකින් ප්‍රේක්ෂක හදවතට සමීප කරයි."),
        q("සම්ප්‍රදායික කෝලම් නර්තන අංග ඇසුරෙන් නූතන හාස්‍යජනක නර්තන නිර්මාණයක් කිරීමේදී පදනම් කරගත යුත්තේ කුමක්ද?", "කෝලම් නැටුමේ චරිත ලක්ෂණ, උපහාසාත්මක අභිනය හා පහතරට බෙර පද", "ශෝකී අවමංගල්‍ය මළබෙර නාද හා විලාප කවි", "දකුණු ඉන්දීය භරත නාට්‍යම් පදම් හා වර්ණම්", "බටහිර සම්භාව්‍ය ඔපෙරා ගායන හා නැටුම්", "දේශීය කෝලම් සම්ප්‍රදාය සතු පොහොසත් සමාජ උපහාසය නව නිර්මාණ සඳහා අගනා මූලාශ්‍රයකි."),
        q("සම්භාව්‍ය නර්තන පද ඇසුරෙන් නිර්මාණය කරන 'මුද්‍රා නාට්‍යයක' කතා පුවත ගලා යාම සඳහා තිබිය යුතු ප්‍රධාන ව්‍යුහය කුමක්ද?", "ආරම්භය, ගැටුම විකාශනය, උච්චතම අවස්ථාව සහ සමාප්තිය", "අවසානය පමණක් පෙන්වීම", "හේතුවක් නැතිව චරිත මාරු කිරීම", "ගීත දහයක් එකට පටිගත කිරීම", "නාට්‍යමය ඒකාග්‍රතාව පවත්වා ගැනීමට පැහැදිලි කතා ව්‍යුහයක් අත්‍යවශ්‍ය වේ."),
        q("ශ්‍රී ලංකාවේ දේශීය නර්තන අධ්‍යාපනයේ ප්‍රථම උපාධි පාඨමාලා බිහිවීමට පදනම වූ ආයතනය වර්තමානයේ හඳුන්වන්නේ කුමන නමකින්ද?", "සෞන්දර්ය කලා විශ්වවිද්‍යාලය", "පේරාදෙණිය කලා පීඨය", "කැලණිය භාෂා පීඨය", "රුහුණු විශ්වවිද්‍යාලය", "හේවුඩ් නමින් හැඳින්වූ රජයේ ලලිත කලා ආයතනය පසුව සෞන්දර්ය කලා විශ්වවිද්‍යාලය බවට පත්විය."),
        q("ශ්‍රී ලාංකේය නර්තනය ජාත්‍යන්තර වේදිකාවේ සම්මානයට පාත්‍ර කරමින් මධ්‍යම පළාතේ සිට බිහිවූ විශිෂ්ට වෙස් නර්තන ශිල්පියෙකු වන්නේ කවුද?", "සූරියඹ ගුණයා හෙවත් නිත්තවෙල ගුණයා ගුරුන්නාන්සේ", "මහාචාර්ය සෙනරත් පරණවිතාන හා මාර්ටින් වික්‍රමසිංහ", "පණ්ඩිත් අමරදේව හා සුනිල් ශාන්ත සංගීතවේදීන්", "මහාචාර්ය එදිරිවීර සරච්චන්ද්‍ර හා සුගතපාල ද සිල්වා", "ගුණයා ගුරුන්නාන්සේ සහ හීන් බබා ධර්මසිරි වැනි ශිල්පීන් දේශීය වෙස් නැටුම ලොවට හඳුන්වා දුන්හ."),
        q("හීන් බබා ධර්මසිරි මහතා විසින් ශ්‍රී ලාංකේය නර්තන ක්ෂේත්‍රයට සිදු කළ අමරණීය දායකත්වය කුමක්ද?", "සමූහ වන්නම් රංගනය හා පහතරට සම්ප්‍රදායේ නව නර්තන ආකෘති නිර්මාණය", "තබ්ලාව නිපදවීම", "සන්නි වෙස්මුහුණු තහනම් කිරීම", "බටහිර ජෑස් නැටුම් පමණක් ගෙන ඒම", "හීන් බබා ධර්මසිරි මහතා ප්‍රසංග වේදිකාවට ගැළපෙන සේ දේශීය නැටුම් අංග විධිමත්ව සැකසුවේය."),
        q("දේශීය නර්තනය හා සංගීතය එක්කරමින් මෙරට නර්තන කලාවේ ගෞරවය ඉහළ නැංවූ 'සෙංකඩගල' හා 'රංග ලලිතා' වැනි කලායතන සිදු කළ සේවය කුමක්ද?", "සාම්ප්‍රදායික නර්තන පරම්පරා රැකගනිමින් නව පරපුර පුහුණු කිරීම", "නැටුම් පොත් විනාශ කිරීම", "බෙර වාදනය නතර කිරීම", "කාන්තාවන්ට නැටුම් තහනම් කිරීම", "පරම්පරාගත කලායතන මෙරට නර්තන උරුමයේ ජීවනාලිය ලෙස ක්‍රියා කරයි."),
        q("ශාරීරික යෝග්‍යතාව අතින් බලන විට නිතිපතා නර්තනයේ යෙදෙන පුද්ගලයෙකු තුළ වර්ධනය වන ප්‍රධාන මානසික හා ස්නායු කුසලතාව කුමක්ද?", "මොළය සහ අත් පා අතර සමායෝජනය (Coordination) හා වේගවත් ප්‍රතිචාර දැක්වීම", "ශරීරයේ චලන ජවය අප්‍රාණික වී වෙහෙස දැනීම", "ප්‍රබල දෘෂ්ටි ආබාධ ඇති වී ඇස් පෙනීම දුර්වල වීම", "කම්මැලිකම ඇති වී උදාසීන ජීවිතයකට හුරු වීම", "සංකීර්ණ අත් මාරු හා පාද චලන එකවර සිදු කිරීම මොළයේ ස්නායු සම්බන්ධතා ශක්තිමත් කරයි."),
        q("පාසල් සිසුවෙකු නර්තනය හැදෑරීමෙන් ඔහුගේ ශරීර ඉරියව්වල (Posture) සිදුවන යහපත් වෙනස කුමක්ද?", "කොන්ද සෘජුව තබා ගැනීම, විශ්වාසවන්ත ඇවිදීම හා පෞරුෂය ඔප් නැංවීම", "උරහිස් ඉදිරියට කුදු වී පහළට නැමී යාම", "දණහිස් හා පාද ඇද වී සමබරතාව ගිලිහී යාම", "නිතර බිම බලාගෙන බියෙන් මෙන් ඇවිදීම", "උඩරට හා සම්භාව්‍ය නර්තන ඉරියව් සිරුරේ සෘජු බව හා අභිමානවත් පෙනුම ස්වාභාවිකව ගොඩනඟයි."),
        q("නර්තනය 'වැඩිහිටි හා රෝගී සෞඛ්‍යයට' පවා උපකාරී වන අඩු බලපෑම් සහිත ක්‍රියාකාරකමක් ලෙස හඳුන්වන්නේ ඇයි?", "වයසට හා ශරීර ශක්තියට ගැළපෙන පරිදි ලය හා චලන පාලනය කළ හැකි බැවින්", "එය ඉතා වේගවත් පිනුම්වලින් පමණක් යුක්ත බැවින්", "හුස්ම රඳවාගෙන කළ යුතු බැවින්", "ආහාර නොගෙන කළ යුතු බැවින්", "මෘදු ලයකින් යුත් රිද්මයානුකූල චලන හන්දිපත් සුවය හා මානසික සතුට රැක ගැනීමට උපකාරී වේ."),
        q("නර්තන පුහුණුව අතරතුරදී ජලය පානය කිරීම සහ පෝෂ්‍යදායී සමබල ආහාර ගැනීම අත්‍යවශ්‍ය වන්නේ ඇයි?", "දහඩිය මගින් පිටවන ජලය පියවා ගැනීමට හා මාංශ පේශි ශක්තිමත්ව තබා ගැනීමට", "ශරීර බර ඉතා අධික කර ගැනීමට හා චලන වේගය අඩු කිරීමට", "නැටුම් පුහුණුව අතරතුර නිදිමත ඇති කර ගැනීමට හා වෙහෙස වැඩි කිරීමට", "ප්‍රසංගය ආරම්භ කිරීමට පෙර ශරීරයේ නම්‍යශීලී බව අඩු කර ගැනීමට", "වෙහෙසකර නර්තන ව්‍යායාමයකදී ජලය හා ඛනිජ ලවණ මෙන්ම ප්‍රෝටීන් හා කාබෝහයිඩ්‍රේට් ශක්තිය සපයයි."),
        q("පහතරට හා උඩරට නර්තන වේදිකාවේ පිනුම් ගැසීම වැනි දුෂ්කර අංග ඉදිරිපත් කිරීමේදී අනතුරු වළක්වා ගැනීමට අනුගමනය කළ යුතු ප්‍රධාන ආරක්ෂක පියවර කුමක්ද?", "සමතලා හා ලිස්සන සුළු නොවන බිමක ප්‍රමාණවත් ඉඩක් සහිතව පුහුණු වීම", "තෙත් හා ලිස්සන සුළු පොළොවක කිසිදු පෙරහුරුවකින් තොරව පිනුම් ගැසීම", "වේදිකා ආලෝකය සම්පූර්ණයෙන් නිවා අඳුරු පරිසරයක පුහුණුව සිදු කිරීම", "ශිල්පීන් අතර පරතරය අඩු තදබද ස්ථානයක වේගවත් චලන ඉදිරිපත් කිරීම", "ආරක්ෂිත පරිසරය හා මූලික තාක්ෂණය අනුගමනය කිරීමෙන් අස්ථි බිඳීම් හා උළුක්කු වළක්වා ගත හැක."),
        q("නර්තන ශිල්පියෙකු වශයෙන් 'සුළු ආබාධයකදී' (උළුක්කුවකදී) ප්‍රථමාධාර වශයෙන් වහාම කළ යුත්තේ කුමක්ද?", "නැටීම නවතා විවේක ගෙන අයිස් තැබීම (RICE ක්‍රමය)", "තවත් වේගයෙන් උඩ පැනීම", "උණු වතුරෙන් තදින් මැඩීම", "වේදනාව නොසලකා ප්‍රසංගය දිගටම කිරීම", "විවේකය, අයිස් තැබීම, පීඩන වෙළුම හා ඉහළ තැබීම ක්‍රීඩා හා නර්තන ආබාධ කළමනාකරණයට අයත්ය."),
        q("වර්තමාන සමාජයේ නර්තනය හා බැඳුණු නවතම නිර්මාණාත්මක රැකියා අවස්ථාවක් වන්නේ කුමක්ද?", "සිනමා, ටෙලිනාට්‍ය හා සංගීත වීඩියෝ සඳහා නර්තන අධ්‍යක්ෂණය", "පුස්තකාල සහායක වෘත්තිය", "නීති හා අධිකරණ වෘත්තිය", "විදුලි බලාගාර කාර්මික වෘත්තිය", "මාධ්‍ය හා විනෝදාස්වාද කර්මාන්තයේ ප්‍රසාරණය සමඟ නර්තන නිර්මාණකරුවන්ට ඉහළ ඉල්ලුමක් ඇත."),
        q("දේශීය නර්තනය පිළිබඳව ශාස්ත්‍රීය පර්යේෂණ කරන විද්වතෙකුට ඇති ප්‍රධානතම වෘත්තීය වටිනාකම කුමක්ද?", "අභාවයට යන ජන නැටුම් හා ශාන්තිකර්ම මූලාශ්‍ර විද්‍යාත්මකව ලේඛනගත කර සුරැකීම", "සාම්ප්‍රදායික නැටුම් කලාව අනෙක් පරපුරෙන් සඟවා තබා ගැනීම", "පැරණි කවි වෙනස් කර වෙනත් රටවල නමින් ප්‍රකාශයට පත් කිරීම", "පාරම්පරික බෙර හඬ පටිගත කිරීම සම්පූර්ණයෙන් තහනම් කරවීම", "පර්යේෂණ හරහා සැඟවී ඇති පැරණි නර්තන උරුමයන් නව පරපුරේ අධ්‍යයනයට හෙළිදරව් කෙරේ."),
        q("සංචාරක හෝටල් හා සංස්කෘතික මධ්‍යස්ථානවල සාම්ප්‍රදායික නැටුම් ඉදිරිපත් කරන ශිල්පීන් අතින් රැකිය යුතු වැදගත්ම වගකීම කුමක්ද?", "දේශීය නර්තනයේ නිවැරදි සම්ප්‍රදාය හා ගෞරවය විකෘති නොකර ඉදිරිපත් කිරීම", "මුදල් සඳහා ඕනෑම අවලස්සන විකෘතියක් කිරීම", "සම්ප්‍රදායික වෙස් ඇඳුම අගෞරව ලෙස ඇඳීම", "වේලාව ඉක්මන් කිරීමට අඩව් මඟ හැරීම", "විදේශිකයන්ට මෙරට සංස්කෘතියේ සැබෑ වටිනාකම පෙන්වීම ශිල්පියාගේ ජාතික වගකීමකි."),
        q("නර්තන විද්‍යාව හා තාක්ෂණය එක්වන 'වේදිකා ශබ්ද පරිපාලනයේදී' බෙර හඬ සමබරව සැකසීම වැදගත් වන්නේ ඇයි?", "නැට්ටුවාට හා ප්‍රේක්ෂකයාට සෑම බෙර අක්ෂරයක්ම පැහැදිලිව හා මිහිරිව ඇසීමට", "වේදිකාවේ ශබ්ද පද්ධතිය අධික ලෙස දෝංකාර දී ප්‍රේක්ෂකාගාරය පිරී යාමට", "නැටුම අතරතුර බෙර හඬ සම්පූර්ණයෙන් නිහඬ කර කවි හඬ පමණක් ඇසීමට", "පසුබිම් ගායකයාගේ කවි ගායනය හා තාලම්පට නාදය සම්පූර්ණයෙන් වසා දැමීමට", "දෝංකාරය හා අධික ඝෝෂාව පාලනය කර ස්වාභාවික බෙර නාදය ඉස්මතු කිරීම තාක්ෂණික දක්ෂතාවකි."),
        q("නර්තන නිර්මාණයක 'ගතික' (Dynamics) යන සංකල්පයෙන් විස්තර කෙරෙන්නේ කුමක්ද?", "චලන සිදු කිරීමේදී යොදන ශක්ති ප්‍රමාණය, බර, හා ගුණාත්මක ස්වභාවය", "සහභාගී වන ශිල්පීන්ගේ ශරීර උස හා බර", "වේදිකාවේ පසුබිම් තිරයේ මූලික වර්ණය", "රංගනය නැරඹීමට පැමිණෙන ප්‍රේක්ෂකයන්ගේ වයස", "එකම පියවරක් මෘදුව පාවෙන සේ හෝ තදින් පහර දෙන සේ සිදු කිරීමෙන් ගතික වෙනස ඇති වේ."),
        q("කණ්ඩායම් නර්තනයකදී සියලුම ශිල්පීන්ගේ 'දෑස් යොමු කිරීම' (Eye Focus) එකම අරමුණකට තබා ගැනීම වැදගත් වන්නේ ඇයි?", "ප්‍රේක්ෂකයාගේ අවධානය නිශ්චිත කේන්ද්‍රයකට ගෙන ඒමට හා රංගනය ප්‍රබල කිරීමට", "වේදිකාවේ පසුබිම් තිරය හා ආලෝක පහන් පිහිටි තැන් පරීක්ෂා කිරීමට", "රංගනය අතරතුර අනෙක් ශිල්පීන් දෙස බලා සිනාසෙමින් ඉඟි මැරීමට", "නැටුම අතරතුර බිම ඇති රංග උපාංග හා අවට පරිසරය නිරීක්ෂණය කිරීමට", "දෑස් වෙනතකට යොමු වුවහොත් රංගනයේ ඒකාග්‍රතාව බිඳී ප්‍රේක්ෂක විශ්වාසය හීන වේ."),
        q("පාසල් නර්තන කණ්ඩායමක් තරගයකට සූදානම් කිරීමේදී 'නියමිත කාල සීමාවට' අනුව අංගය සැකසීම වැදගත් වන්නේ ඇයි?", "නීති රීතිවලට ගරු කිරීම හා රංගනයේ උච්චතම අවස්ථාව අහිමි නොවී අවසන් කිරීමට", "විනිශ්චය මණ්ඩලයට ලකුණු සටහන් කිරීමට කාලය ඉතිරි නොකර වේගයෙන් නැටීමට", "පසුබිම් සංගීතය හා බෙර වාදනය අතරමැදදී නවතා අසම්පූර්ණව පිටව යාමට", "මූලික පූජා පද හා කස්තිරම් ඉදිරිපත් නොකරම වේදිකාවෙන් බැස යාමට", "විනයානුකූල කාල කළමනාකරණය සෑම කලා නිර්මාණයකම වෘත්තීයභාවය පිළිබිඹු කරයි."),
        q("නර්තන කලාවේදී 'ස්වාභාවික වස්තූන් හා අවි ආයුධ' වෙනුවට වේදිකා ආදර්ශක (Props) භාවිතයේදී සැලකිය යුත්තේ කුමක්ද?", "සැහැල්ලු බව, ආරක්ෂිත බව සහ නැටුම් පියවර සමඟ සුමටව හැසිරවීමේ පහසුව", "හැකිතාක් බර යකඩවලින් හා ඝන ලෝහවලින් සාදා වේදිකාවේ තැබීම", "තියුණු මුවහත් සහිත සැබෑ කඩු හා ආයුධ රංගනයේදී පාවිච්චි කිරීම", "නැටුමේ තේමාවට කිසිසේත් අදාළ නොවන බර භාණ්ඩ වේදිකාවට ගෙන ඒම", "කලගෙඩි, චාමර, කඩු හා පන්දම් ආදී උපාංග ආරක්ෂිතව හා අලංකාරව හැසිරවීම අත්‍යවශ්‍යය."),
        q("දේශීය නර්තනයට නූතන තරුණ පරපුරේ ආකර්ෂණය දිනා ගැනීමට ගත හැකි වඩාත්ම නිර්මාණශීලී හා ධනාත්මක පියවර කුමක්ද?", "සාම්ප්‍රදායික හරය රැකගනිමින් ආකර්ෂණීය වේදිකාකරණය හා නව නිර්මාණ ඉදිරිපත් කිරීම", "දේශීය නැටුම් සියල්ල පාසල් විෂය මාලාවෙන් සම්පූර්ණයෙන් ඉවත් කිරීම", "පැරණි බෙර පද හා වන්නම් කවි නව පරපුරට නොපෙන්වා මකා දැමීම", "නර්තන විෂයය ජාතික මට්ටමේ ප්‍රායෝගික විභාගවලින් අයින් කර දැමීම", "සම්ප්‍රදායේ අභිමානය නූතන කලා මාධ්‍ය හරහා සමාජගත කිරීමෙන් තරුණ පෙළ එය වැළඳ ගනී."),
        q("නර්තන ඉතිහාසයේ සඳහන් පරිදි උඩරට හා පහතරට සම්ප්‍රදායන් දෙකෙහිම පිරිමි හා කාන්තා නර්තන අංග වෙන්ව පැවතුණත් අද වන විට සිදුව ඇති වෙනස කුමක්ද?", "වේදිකා සෞන්දර්ය අධ්‍යාපනය තුළ කාන්තා හා පිරිමි දෙපාර්ශ්වයටම සම අවස්ථා හිමි වීම", "සාම්ප්‍රදායික නර්තන අධ්‍යාපනය පාසල් හා විශ්වවිද්‍යාල තුළ සම්පූර්ණයෙන් නතර වීම", "උඩරට වෙස් ඇඳුම පැළඳීම පිරිමි ශිල්පීන්ටද සම්පූර්ණයෙන්ම අහිමි වී යාම", "කාන්තාවන්ට කලගෙඩි හා රබන් නැටුම් ඉදිරිපත් කිරීම තහනම් කර දැමීම", "පාසල් හා විශ්වවිද්‍යාල අධ්‍යාපනය මගින් සියලු සිසුන්ට නර්තන ශිල්පය සමානව හැදෑරීමට අවස්ථාව ලැබී ඇත."),
        q("නර්තන ශිල්පියෙකු ප්‍රසංගයක් අවසානයේදී වේදිකාවෙන් පිටවීමට පෙර ප්‍රේක්ෂකයාට ආචාර කරන 'අවසන් කළමනාකරණය' (Curtain Call) වැදගත් වන්නේ ඇයි?", "ප්‍රේක්ෂකයන්ට හා වාද්‍ය ශිල්පීන්ට ස්තූති කර ගෞරවයෙන් සමුගැනීමට", "වේදිකාව ඉක්මනින් අස් කිරීමට", "ඇඳුම් ප්‍රදර්ශනය කර මුදල් ඉල්ලීමට", "බෙර වාදකයාට දොස් පැවරීමට", "සුහද සිනහවකින් හා අංජලී මුද්‍රාවෙන් සමුගැනීම ප්‍රේක්ෂක හදවතේ ප්‍රසංගය සදාකාලික කරයි."),
        q("නර්තන ශිල්පය පරම්පරා ගණනාවක් තිස්සේ නොනැසී පැවතීමට ප්‍රධාන හේතුව කුමක්ද?", "සංස්කෘතික විශ්වාස, ශාන්තිකර්ම, ගුරු ශිෂ්‍ය පරම්පරා හා නූතන අධ්‍යාපන පද්ධතිය", "පැරණි රන් ආකර සොයා ගැනීම හා ධනවත් වීම", "නගරබද කාර්මික ක්ෂේත්‍ර හා නිෂ්පාදන වැඩි වීම", "විදේශ ආක්‍රමණ මගින් බලපෑම් එල්ල වීම", "ජන ජීවිතය, ආගමික චාරිත්‍ර හා පාසල් අධ්‍යාපනය නර්තනයේ පැවැත්ම තහවුරු කර ඇත."),
        q("නර්තනයේදී 'තාල දෝෂයක්' (Out of Rhythm) සිදු වූ විට ශිල්පියෙකු වේදිකාව මත කළ යුතු බුද්ධිමත්ම ක්‍රියාව කුමක්ද?", "කලබල නොවී බෙර නාදයට හා තාලම්පටට සවන් දී මීළඟ සම ස්ථානයේදී යළි එක්වීම", "වේදිකාවේ මැද නැටුම නවතා අඬන්න පටන් ගැනීම", "බෙර වාදකයා දෙස බලා බැණ වැදීම", "සියල්ල අතහැර වේදිකාවෙන් දිව යාම", "අත්දැකීම් සහිත නැට්ටුවා ක්ෂණික තාල සවන්දීමෙන් ප්‍රේක්ෂකයාට නොදැනෙන සේ යළි තාලයට එක්වේ."),
        q("සම්ප්‍රදායික 'ගම්මඩු' හා 'කොහොඹා කංකාරි' වැනි ශාන්තිකර්මවල තාල හා රිද්ම රටා අධ්‍යයනය කිරීමෙන් නවීන නර්තනකරුවා ලබන දැනුම කුමක්ද?", "දුර්ලභ හා සංකීර්ණ සිංහල තාල වර්ග හා ස්වාභාවික භාව රංගන රටා හඳුනා ගැනීම", "බටහිර සම්භාව්‍ය පියානෝ හා වයලීන් වාද්‍ය භාණ්ඩ හඳුනා ගැනීම", "නවීන වේදිකා ආලෝක උපකරණ අලුත්වැඩියා කිරීමේ තාක්ෂණය ඉගෙනීම", "ප්‍රසංග ශාලාවල ආසන පෙළගැස්ම හා ශාලා කළමනාකරණය දැන ගැනීම", "ශාන්තිකර්ම යනු අපේ පැරණිතම නර්තන, සංගීත හා නාට්‍ය ශිල්ප ක්‍රමවල ජීවමාන ගබඩාවයි."),
        q("නව නර්තන නිර්මාණයක 'නාමකරණය' (Title) තෝරා ගැනීමේදී වැදගත් වන ලක්ෂණය කුමක්ද?", "නිර්මාණයේ හරය හා තේමාව කෙටියෙන්, ආකර්ෂණීයව ප්‍රකාශ වන නමක් වීම", "කතාව සම්පූර්ණයෙන් අමතක වන දිගු ඡේදයක් වීම", "ප්‍රේක්ෂකයාට නොතේරෙන අංක ගොඩක් යෙදීම", "වෙනත් නිර්මාණයක නමක් කෙලින්ම පිටපත් කිරීම", "පැහැදිලි හා කාව්‍යමය නාමයක් ප්‍රේක්ෂකයා තුළ නිර්මාණය පිළිබඳ කුතුහලය ඇති කරයි."),
        q("වෘත්තීය නර්තන පුහුණුකරුවෙකු සිසුන්ට නව පියවරක් ඉගැන්වීමේදී අනුගමනය කළ යුතු වඩාත්ම ඵලදායී ක්‍රමවේදය කුමක්ද?", "සරල කොටස්වලට බෙදා, මන්දගාමීව පෙන්වා, ක්‍රමයෙන් තාල ලයට ගෙන ඒම", "පළමු දිනයේම අපහසුම පිනුම කිරීමට බල කිරීම", "උදාහරණ නොපෙන්වා ලියන්න දීම පමණක්", "සිසුන් වැරදුණු විට ඉවත් කිරීම", "සරල සිට සංකීර්ණ දක්වා පියවරෙන් පියවර යාම නිවැරදි අධ්‍යාපනික මනෝවිද්‍යා ක්‍රමයයි."),
        q("දේශීය නර්තන සංස්කෘතිය තුළ 'ගුරු පඬුරු' සහ 'වැඳ නමස්කාර කිරීම' මගින් ප්‍රකාශ වන සදාචාරාත්මක වටිනාකම කුමක්ද?", "කලාව කෙරෙහි ඇති ගෞරවය, කෘතවේදී බව සහ විනයානුකූල බව", "මුදලට හා ප්‍රසිද්ධියට කලාව විකෘති කර පෙන්වීම", "පැරණි සාම්ප්‍රදායික ගුරුකුල ක්‍රම හෙළා දැකීම", "සහෝදර ශිල්පීන් අතර තරගකාරී අහංකාරය පෙන්වීම", "ගුරුවරයා දැනුමේ මූලාශ්‍රය ලෙස සලකා ගෞරව කිරීම පෙරදිග කලා සම්ප්‍රදායේ පදනමයි."),
        q("නර්තන ප්‍රසංගයක සමස්ත සාර්ථකත්වය ඇගයීමේදී සැලකිල්ලට ගන්නා ප්‍රධාන සාධක හතර මොනවාද?", "ශිල්පීය දක්ෂතාව, සංගීතය, වේදිකා සැලසුම හා රසවින්දනය", "ප්‍රේක්ෂකාගාරයේ බිත්ති වර්ණය හා අසුන් ප්‍රමාණය", "වේදිකාවේ උස, දිග හා තිර රෙදිවල බර", "ආරාධිත අමුත්තන්ගේ ඇඳුම් පැළඳුම් හා ආසන පිළිවෙළ", "මෙම අංග සියල්ල සමබරව සම්බන්ධ වූ විට උසස් කලාත්මක ප්‍රසංගයක් බිහිවේ."),
        q("නර්තන කාල ගණනයේදී 'දුගුන්' ලය යනු කුමක්ද?", "එක් මාත්‍රාවක් තුළ පියවර දෙකක් සිදු කිරීම", "එක් මාත්‍රාවක් තුළ පියවර හතරක් සිදු කිරීම", "මාත්‍රා හතරකට වරක් එක් පියවරක් තැබීම", "වේදිකාවේ තාලය සම්පූර්ණයෙන් නතර කිරීම", "සාමාන්‍ය තාල වේගය මෙන් දෙගුණයක පාද හා අත් චලන රටාවක් පෙන්වීම දුගුන් නම් වේ."),
        q("තාල ශාස්ත්‍රයේදී 'චෞගුන්' ලය යනුවෙන් හඳුන්වනු ලබන්නේ කුමන වේග රටාවද?", "එක් මාත්‍රාවකට චලන හතර බැගින් යෙදෙන වේගය", "මාත්‍රා දෙකකට එක් චලනයක් යෙදෙන වේගය", "ඉතා සෙමින් ගමන් කරන විලම්බ වේගය", "පියවර නොතබා ස්ථාවරව සිටින අවස්ථාව", "කස්තිරම් හා තීර්මානම් උච්ච අවස්ථාවේදී චෞගුන් හෙවත් සිව්ගුණ වේගය බහුලව යෙදේ."),
        q("සම්ප්‍රදායික උඩරට නැටුමේදී 'සුරල් පද' යනුවෙන් හඳුන්වන්නේ කුමන බෙර පද කොටසද?", "බෙර ඇස දෙපස වේගයෙන් රෝල් කර වැයෙන අලංකාර පද", "තාලම්පට පමණක් ගසා නවතන විරාම කොටස", "කවියක් ගායනා කිරීමෙන් පසු ඇති නිහඬතාව", "ප්‍රේක්ෂකයා ආචාර කිරීමට වැයෙන සරල පදය", "සුරල් වාදනය නර්තන අංගයට ගාම්භීර හා චමත්කාරජනක නිමාවක් එක් කරයි."),
        q("නර්තන නිර්මාණයකදී 'තේමා ගීතය' හෝ පසුබිම් ගායනය සැලසුම් කිරීමේදී මූලිකව සැලකිය යුත්තේ කුමක්ද?", "ගීතයේ වචන අර්ථය හා රිද්මය නැටුමට ගැළපීම", "ගීතයේ ශබ්දය හැකිතාක් අඩු මට්ටමක තැබීම", "භාෂාව පැහැදිලි නොවන සේ වේගයෙන් ගැයීම", "තාලය වෙනස් වන සෑම විටම ගීතය කපා හැරීම", "පසුබිම් ගායනය නැටුම් ශිල්පියාගේ භාව ප්‍රකාශනය තීව්‍ර කරන ප්‍රධාන සහායකයෙකි."),
        q("වේදිකා නර්තනයකදී 'කවි පදයට අභිනය දැක්වීම' (Bharatha / Padam) යනු කුමක්ද?", "කවියේ වචනවල අර්ථය හස්ත මුද්‍රා හා මුහුණෙන් රඟපෑම", "කවිය අවසන් වූ පසු පමණක් පාද ගැසීම", "බෙර වාදනය නතර වන තුරු නිහඬව සිටීම", "වේදිකාවේ පිටුපස හැරී ඉඳ ගැනීම", "ශාස්ත්‍රීය නර්තනයේදී වචනාර්ථය ශාරීරික හා මානසික අභිනයෙන් සජීවීව ඉදිරිපත් කෙරේ."),
        q("උඩරට නැටුමේ 'වට්ටම්' හා 'තානම්' අතර පවතින ප්‍රධාන වෙනස කුමක්ද?", "තානම තාල රහිතව ගැයෙන අතර වට්ටම තාලයට නැටේ", "තානම බෙරයෙන් වැයෙන අතර වට්ටම කටින් ගැයේ", "දෙකම වේදිකාවෙන් බැසීමේදී පමණක් යොදයි", "වට්ටම පහතරටටත් තානම විදේශයටත් පමණක් සීමා වේ", "තානමෙන් රාගය හා හැඟීම විවෘත කෙරෙන අතර පසුව නියමිත තාලයට පද නැටේ."),
        q("නව නර්තන අංගයක 'ප්‍රවේශය' (Entrance) ආකර්ෂණීය වීම ප්‍රේක්ෂකයාට වැදගත් වන්නේ ඇයි?", "ප්‍රසංගයේ පළමු තත්පරයේම ප්‍රේක්ෂක අවධානය දිනා ගැනීමට", "ශිල්පීන්ට වේදිකාවෙන් පිටවීම ඉක්මන් කිරීමට", "ආලෝක පද්ධතිය නිවා දැමීම පහසු කිරීමට", "වෙස්මුහුණු ගලවා තැබීමට ඉඩ ලබා ගැනීමට", "නැටුමක සාර්ථක ආරම්භය මුළු නිර්මාණය කෙරෙහිම ප්‍රේක්ෂක උනන්දුව රඳවා තබයි."),
        q("වේදිකාවේ 'මධ්‍ය ස්ථානය' (Center Stage) සාමාන්‍යයෙන් නර්තන නිර්මාණයකදී භාවිත කරන්නේ කුමන චරිතය ඉස්මතු කිරීමටද?", "ප්‍රධාන චරිතය හෝ නාටකීය මූලික සිදුවීම", "වේදිකා පිරිසිදු කරන්නාගේ ගමන් මාර්ගය", "බෙර වාදකයාගේ බඩු බාහිරාදිය තැබීමට", "පසුබිම් තිරය මාරු කරන සේවකයන් සඳහා", "වේදිකාවේ මධ්‍යය ප්‍රේක්ෂක දෘෂ්ටියට සෘජුවම ලක්වන ප්‍රබලම ස්ථානයයි."),
        q("නර්තන නිර්මාණයකදී 'චලන පුනරාවර්තනය' (Repetition) සීමිතව භාවිත කිරීමෙන් අත්වන ප්‍රයෝජනය කුමක්ද?", "ප්‍රධාන තේමා චලනය ප්‍රේක්ෂක මතකයේ තහවුරු වීම", "නර්තන ශිල්පීන්ට නව පියවර අමතක වී යාම", "සංගීත වාදනය අනවශ්‍ය ලෙස දිගු කර ගැනීම", "ප්‍රේක්ෂකයන් තුළ කම්මැලිකම ඇති කරවීම", "වැදගත් චලන රටාවක් සුදුසු අවස්ථාවලදී යළි දැක්වීමෙන් නිර්මාණයේ අනන්‍යතාව රැකේ."),
        q("නූතන නර්තන අධ්‍යක්ෂණයේදී 'පරිසර හිතකාමී වේදිකා සැරසිලි' සඳහා වඩාත් සුදුසු ද්‍රව්‍ය මොනවාද?", "උණ බට, ගොක් කොළ, මැටි හා කපු රෙදි", "වීදුරු තහඩු, ලෝහ පටි හා තාර බැරල්", "ෆෝම් පුවරු, පොලිතින් පටි හා නයිලෝන් තිර", "ඇලුමිනියම් තහඩු, යකඩ දඬු හා ඉටි රෙදි", "ස්වාභාවික ද්‍රව්‍ය භාවිතය දේශීය සෞන්දර්යය මෙන්ම පරිසර සංරක්ෂණයද ප්‍රවර්ධනය කරයි."),
        q("සිංහල නර්තන වංශයේ එන 'දික්තල කාලගෝල' හෝ 'සඳකිඳුරු' කතා පුවත් නව මුද්‍රා නාට්‍ය සඳහා තෝරා ගැනීමේ ඇති වටිනාකම කුමක්ද?", "දේශීය සාහිත්‍යමය හා සදාචාරමය උරුමය රසවත්ව සමාජගත කිරීම", "විදේශීය ඉතිහාස පොත් පමණක් ප්‍රචාරය කිරීම", "සාම්ප්‍රදායික කවි හා බෙර සංගීතය බැහැර කිරීම", "කෙටි චිත්‍රපට සඳහා පමණක් යොදා ගැනීම", "ජාතක කතා හා ගැමි නාටක දේශීය මුද්‍රා නාට්‍ය නිර්මාණ සඳහා අතිශයින් සරු මූලාශ්‍ර වේ."),
        q("නර්තන පුහුණුවේදී 'ශ්වසන පාලනය' (Breath Control) පුහුණු කිරීම අවශ්‍ය වන්නේ ඇයි?", "දිගු වේලාවක් හතිය නොගෙන රිද්මය රැක නැටීමට", "හුස්ම ගැනීම සම්පූර්ණයෙන් නවතා දැමීමට", "උස් හඬින් කෑගසමින් වේදිකාව දෙවනත් කිරීමට", "ශරීර උෂ්ණත්වය අඩු මට්ටමක රඳවා තැබීමට", "නිවැරදි ප්‍රාශ්වාස ආශ්වාස පාලනය ශක්තිය රැකගැනීමට හා කවි ගායනයට උදව් වේ."),
        q("වෘත්තීය නර්තන ශිල්පියෙකුගේ 'ආහාර රටාව' ප්‍රසංග දිනයේදී කෙසේ සැලසුම් විය යුතුද?", "පහසුවෙන් දිරවන සමබල සැහැල්ලු ආහාර හා ප්‍රමාණවත් ජලය", "ඉතා අධික තෙල් හා මස් සහිත බර ආහාර", "මුළු දිනය පුරාම කිසිදු ආහාරයක් නොගෙන සිටීම", "පැණි බීම හා කෘත්‍රිම රසකාරක පමණක් ගැනීම", "බර ආහාර උදර අපහසුතා ඇති කරන බැවින් රංගනයට පෙර සැහැල්ලු පෝෂ්‍යදායී ආහාර සුදුසුය."),
        q("ශ්‍රී ලංකාවේ සාම්ප්‍රදායික 'පන්තේරු නැටුම' ඉදිරිපත් කිරීමේදී අත්‍යවශ්‍ය වන ශාරීරික කුසලතාව කුමක්ද?", "පන්තේරුව ඇඟිලි අතර කරකැවීමේ වේගවත් හා සුමට හුරුව", "බිම වැතිරී හිසින් බෙරය තල්ලු කර ගෙන යාම", "එක් තැනක නොසෙල්වී වාඩි වී ගීත ගැයීම", "වෙස්මුහුණු දෙකක් එකවර මුහුණේ බැඳ ගැනීම", "පන්තේරුව ඉහළට විසි කර නැවත තාලයට අල්ලා ගැනීම පුහුණුවෙන් ලබන දක්ෂතාවකි."),
        q("දේශීය නර්තන ප්‍රසංගයකදී 'කළගෙඩි නැටුම' නව නිර්මාණශීලීව ඉදිරිපත් කිරීමේදී යොදාගත හැකි ආරක්ෂිත කළගෙඩි විශේෂය කුමක්ද?", "සැහැල්ලු පිත්තල, දැව හෝ ශක්තිමත් කෙඳි කළගෙඩි", "තද බරින් යුත් වීදුරු හෝ ගල් කළගෙඩි", "පහසුවෙන් කැඩී තුවාල වන පෝසිලේන් බඳුන්", "උණු ජලය පිරවූ විශාල යකඩ බැරල්", "වේදිකාව මත බිඳී තුවාල සිදුවීම වැළැක්වීමට සැහැල්ලු නොබිඳෙන කළගෙඩි යෝග්‍ය වේ."),
        q("නර්තන කලාව තුළ 'සෞන්දර්ය රසවින්දනය' වර්ධනය වීමෙන් ශිෂ්‍යයාගේ එදිනෙදා ජීවිතයට ලැබෙන යහපත කුමක්ද?", "කලාව, ස්වභාවධර්මය හා අන් අයගේ හැඟීම් සියුම්ව තේරුම් ගැනීම", "අනෙක් විෂයයන් කෙරෙහි ඇති උනන්දුව හීන වීම", "සමාජ සම්බන්ධතා අඩු වී හුදෙකලා වීම", "ප්‍රචණ්ඩකාරී හැසිරීම් වැඩි වීම", "සෞන්දර්ය අධ්‍යාපනය මානසික සංයමය හා සංවේදී හදවතක් ගොඩනඟයි."),
        q("උඩරට නර්තනයේ 'ගැටබෙර වාදනය' හා 'නැට්ටුවා' අතර ඇති සම්බන්ධය වඩාත් හොඳින් විස්තර වන්නේ කෙසේද?", "දෙදෙනා එකිනෙකාගේ ඉඟි හා තාලය හඳුනාගෙන එකට ගමන් කිරීම", "නැට්ටුවා වාදකයාට පිටුපස හරවා වෙනත් තාලයකට නැටීම", "බෙර වාදකයා නැටුම නොබලා ඕනෑම පදයක් ගැසීම", "දෙදෙනා දෙවිදියකින් වේදිකාවේ තරග කිරීම", "වාදකයාගේ මාත්‍රා ශක්තිය හා නැට්ටුවාගේ පියවර ඒකාබද්ධ වීම සාර්ථක රංගනයේ රහසයි."),
        q("නර්තන නිර්මාණයකදී 'අභ්‍යන්තර අවකාශය' (Personal Space) හා 'පොදු අවකාශය' (General Space) වෙන් කර හඳුනා ගන්නේ කෙසේද?", "තම ශරීරය වටා ඇති ඉඩ පෞද්ගලික අවකාශය වන අතර මුළු වේදිකාව පොදු අවකාශයයි", "ප්‍රේක්ෂකාගාරය පෞද්ගලික අවකාශය වන අතර පිටුපස කාමරය පොදු අවකාශයයි", "වෙස්මුහුණු පෙට්ටිය පෞද්ගලික අවකාශය වන අතර ඇඳුම් කාමරය පොදු අවකාශයයි", "පෞද්ගලික අවකාශය නර්තන වේදිකාවට කිසිසේත් අදාළ නොවේ", "ශිල්පීන් එකිනෙකාගේ ගැටීමකින් තොරව නිර්මාණශීලීව චලනය වීමට මෙම දැනුම අත්‍යවශ්‍යය."),
        q("සමූහ නර්තනයකදී 'වෘත්තාකාර රටාව' (Circle Formation) බහුලව යොදාගනු ලබන්නේ කුමන හැඟීමක් ඉස්මතු කිරීමටද?", "එකමුතුකම, සමානාත්මතාව හා ප්‍රීතිමත් ජන සහභාගීත්වය", "යුද පිටියේ වෙන්වීම හා තනිකම", "බියජනක සැඟවී යාම", "නාට්‍යයේ සම්පූර්ණ බිඳවැටීම", "කවි හා රබන් නැටුම්වලදී මෙන්ම වෘත්ත රටාව සාමූහික බැඳීම පෙන්වීමට කදිමය."),
        q("දේශීය නර්තන සංරක්ෂණයේදී 'වාචික සම්ප්‍රදාය' පමණක් ප්‍රමාණවත් නොවන බව අද පිළිගන්නේ ඇයි?", "පරම්පරා මාරුවේදී කවි, පද හා සියුම් මුද්‍රා අමතක වී යා හැකි බැවින්", "කටින් කියන කිසිදු කවියක් කිසිවෙකුට නොඇසෙන බැවින්", "පැරණි බෙර පද ලිවීමට සිංහල අකුරු නොමැති බැවින්", "ප්‍රායෝගික නැටුම් පුහුණුව අනවශ්‍ය බව තීරණය වූ බැවින්", "පොත්පත්, ප්‍රස්තාර හා ශ්‍රව්‍ය දෘශ්‍ය සංරක්ෂණය මඟින් පැරණි උරුමය නිවැරදිව රැකේ."),
        q("නර්තන විද්‍යාවේ එන 'තාල ප්‍රස්තාරය' (Rhythmic Notation) ඉගෙනීමෙන් ශිෂ්‍යයාට ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "ඕනෑම බෙර පදයක් හා තාල රටාවක් නිවැරදිව කියවා වාදනය කිරීම", "වෙස් ඇඳුමේ ආභරණ සෑදීමට අවශ්‍ය රිදී බර ප්‍රමාණය ගණනය කිරීම", "රංග වේදිකාවේ පසුබිම් තිරයේ ආලෝක වර්ණ සංයෝජනය තෝරා ගැනීම", "සාම්ප්‍රදායික කෝලම් වෙස්මුහුණු කැපීමට සුදුසු ලී වර්ග හඳුනා ගැනීම", "තිත්, ඉරි හා මාත්‍රා සලකුණු මඟින් සංකීර්ණ පද නිරවුල්ව සටහන් කර තබා ගත හැකිය."),
        q("පහතරට හා සබරගමු නර්තන අංගයන්හිදී පන්දම් (Pandam) දල්වා නැටීමෙන් ලැබෙන ප්‍රධාන වේදිකා අලංකාරය කුමක්ද?", "ආලෝක රටා මැවීම හා ශාන්තිකර්මයේ ගුප්ත පූජනීය බව ඉස්මතු කිරීම", "වේදිකාවේ දූවිලි ඉවත් කර ගැනීම", "බෙර සම අධික ලෙස රත් කර පිළිස්සීම", "ප්‍රේක්ෂකාගාරය දුමෙන් පුරවා දැමීම", "රාත්‍රී එළිමහන් රංග මණ්ඩප ආලෝකවත් කිරීමට හා ගිනි මැවීම් පෙන්වීමට පන්දම් යොදයි."),
        q("නර්තන ශිල්පියෙකුගේ 'මුහුණේ අංග රචනය' (Stage Make-up) සාමාන්‍ය එදිනෙදා සැරසීමට වඩා තදින් කරන්නේ ඇයි?", "ප්‍රබල වේදිකා ආලෝකය යටතේ දුර සිටින ප්‍රේක්ෂකයාට මුහුණ පැහැදිලිව පෙනීමට", "ශිල්පියාගේ මුහුණ සම්පූර්ණයෙන් හඳුනාගත නොහැකි වන සේ වැසීමට", "නැටුම අතරතුර දහඩිය ගැලීම වැළැක්වීමට", "වෙස්මුහුණු පැළඳීම සම්පූර්ණයෙන් අවලංගු කිරීමට", "තීව්‍ර විදුලි ආලෝකය නිසා මුහුණ සුදුමැලි නොවී ඇස් හා තොල් ඉරියව් පැහැදිලිව දිස්වීමට එය උදව් වේ."),
        q("වේදිකාවක 'දකුණු පස' හා 'වම් පස' (Stage Right / Stage Left) නිර්ණය කරන්නේ කවරෙකුගේ දෘෂ්ටිය අනුවද?", "වේදිකාව මත ප්‍රේක්ෂකයා දෙසට මුහුණ ලා සිටින නර්තන ශිල්පියාගේ පැත්ත අනුව", "ප්‍රේක්ෂකාගාරයේ පසුපස පේළියේ සිටින අයෙකුගේ පැත්ත අනුව", "ශාලාවෙන් පිටත සිටින ආරක්ෂකයාගේ පැත්ත අනුව", "වේදිකා පසුපස තිරයේ වර්ණය අනුව", "සම්මත වේදිකා නීතිය අනුව නැට්ටුවාගේ දකුණු අත පැත්ත Stage Right ලෙස සැලකේ."),
        q("නර්තන නිර්මාණයකදී 'සමූහ ගොඩනැංවීම්' (Tableau) යනුවෙන් හඳුන්වන උපක්‍රමය කුමක්ද?", "සංගීතයේ විරාමයකදී ශිල්පීන් චිත්‍රයක් මෙන් නිශ්චල ඉරියව්වක රැඳී සිටීම", "සියලු ශිල්පීන් එකවර වේදිකාවෙන් පැන යාම", "බෙර වාදකයා වේදිකාව මැද නිදා ගැනීම", "ප්‍රේක්ෂකයන් නැඟිට අත්පුඩි නොගසා සිටීම", "නාටකීය නිශ්චල රූපයක් මැවීමෙන් ප්‍රේක්ෂක මනසෙහි එම ජවනිකාව තදින් සනිටුහන් වේ."),
        q("පාසල් මට්ටමේ 'නව නිර්මාණ නර්තන තරගයකදී' විනිශ්චය මණ්ඩලය වැඩි අවධානයක් යොමු කරන්නේ කුමන අංශයටද?", "තේමා උචිත බව, චලන නව්‍යතාව, තාල ඥානය හා ඉදිරිපත් කිරීම", "රංග වස්ත්‍ර සඳහා වැය කළ මුදල් ප්‍රමාණය", "පාසලේ නම හා ශිෂ්‍ය සංඛ්‍යාව පමණක්", "වේදිකාවේ පාවිච්චි කළ පසුතල පුවරු ප්‍රමාණය", "නිර්මාණශීලී සංකල්පය, ශිල්පීය පරිණත බව හා සංගීත සුසංයෝගය ප්‍රධාන නිර්ණායක වේ."),
        q("ශ්‍රී ලාංකේය නර්තන ශිල්පීන් ජාත්‍යන්තර උළෙලවලදී දේශීය නැටුම් ඉදිරිපත් කිරීමෙන් රටට අත්වන ප්‍රධාන කීර්තිය කුමක්ද?", "ශ්‍රී ලංකාවේ අනන්‍ය සංස්කෘතික අභිමානය ලොවට ප්‍රදර්ශනය වීම", "වෙනත් රටවල නැටුම් සම්පූර්ණයෙන් අමතක වී යාම", "දේශීය බෙර වාදන ශිල්පය නැවතී යාම", "ජාත්‍යන්තර සංචාරකයන් මෙරටට පැමිණීම අඩු වීම", "සාම්ප්‍රදායික නර්තන කලාව ශ්‍රී ලංකාවේ සංස්කෘතික අනන්‍යතාව ලොව හමුවේ ඔසවා තබයි."),
        q("නර්තනය හදාරන සිසුවෙකුට 'ලය මාරුව' (Change of Tempo) පුහුණු වීමේදී ඇතිවන ප්‍රධාන අභියෝගය කුමක්ද?", "මන්දගාමී සිට වේගවත් ලයට යාමේදී තාල මාත්‍රාව නොබිඳී තබා ගැනීම", "පසුබිම් තිරයේ ලණු ලිහා ගැනීමට නොහැකි වීම", "ඇඳුම්වල බොත්තම් ගැලවී යාම", "ප්‍රේක්ෂකාගාරයේ විදුලි පහන් පාලනය කිරීම", "වේගය වෙනස් වන සෑම විටම චලන නිරවද්‍යතාව රැකගැනීම පුහුණුවෙන් ලැබෙන දක්ෂතාවකි."),
        q("උඩරට නැටුමේ 'පන්තේරු' හා 'උඩැක්කි' නර්තන අංග සාමාන්‍යයෙන් කවර පරිසරයක රඟ දැක්වූ ඒවාද?", "දළදා පෙරහැර, විහාර උත්සව හා රාජ සභා මංගල්‍යයන්හිදී", "අම්බලන්ගොඩ කෝලම් රඟමඬලේ විකට පෙළපාලියේදී", "රාත්‍රී සන්නි යාගයේ යක් වෙස්මුහුණු පෙළපාලියේදී", "පැරණි ගැමි රබන් ක්‍රීඩා හා ඔන්චිලි වාරම් අතරේදී", "මෙම සම්භාව්‍ය නර්තන අංග ආගමික හා රාජකීය උත්සව අලංකාර කිරීමට යොදා ගැනුණි."),
        q("නව නිර්මාණාත්මක නැටුමක් සැලසුම් කිරීමේදී 'වේදිකා සැලැස්ම' (Floor Pattern) කඩදාසියක ඇඳීම වැදගත් වන්නේ ඇයි?", "ශිල්පීන් ගමන් කරන මාර්ග හා රටා පැහැදිලිව පෙළගස්වා ගැනීමට", "චිත්‍ර විභාගයකට ලකුණු ලබා ගැනීමට පමණක්", "වේදිකාවේ ලී කැබලි කැපීමට මැන ගැනීමට", "ප්‍රේක්ෂකයන්ට පින්තූර බෙදා දීමට", "චලන මාර්ග කල්තියා සටහන් කිරීමෙන් කණ්ඩායම පුහුණු කිරීම පහසු හා නිරවුල් වේ."),
        q("වේදිකාවේ පිටුපස සිට ඉදිරියට පැමිණීම 'ශක්තිමත් ගමනක්' ලෙස හැඳින්වෙන්නේ ඇයි?", "ශිල්පියා ප්‍රේක්ෂකයාට සමීප වන විට රංග බලය හා අවධානය වැඩි වන බැවින්", "පිටුපසට යාමට වඩා ඉදිරියට ඇවිදීම ලෙහෙසි බැවින්", "වේදිකාවේ පිටුපස කොටසේ ආලෝකය අඩු බැවින් පමණක්", "බෙර වාදකයා පිටුපසින් ඉවත් වන බැවින්", "ප්‍රේක්ෂකයා දෙසට මුහුණ ලා පැමිණීම චරිතයේ අභිමානය හා ප්‍රබලත්වය පෙන්වයි."),
        q("දේශීය නර්තනයේදී 'තාලම්පට' නොමැති අවස්ථාවක පුහුණුව සඳහා තාලය ලබා දීමට භාවිත කරන සාම්ප්‍රදායික ක්‍රමය කුමක්ද?", "දඬියම් කඳට කෝටුවකින් ගැසීම හෝ අතින් තාල තැබීම", "වීදුරු බෝතලයකට හැන්දකින් තට්ටු කිරීම", "කඩදාසි ඉරා ශබ්ද ඇති කිරීම", "සපත්තු එකට ගැසීමෙන් ශබ්දය ගැනීම", "පුහුණුවේදී ගුරුවරයා දඬියම් ලීයට පහර දෙමින් හෝ අතින් තාල ගසමින් මාත්‍රා පෙන්වයි."),
        q("නර්තන විෂයය හරහා සිසුන් තුළ 'සංස්කෘතික සංහිඳියාව' වර්ධනය කළ හැක්කේ කෙසේද?", "ශ්‍රී ලංකාවේ සියලු ජන කොටස්වල සාම්ප්‍රදායික නර්තන අගය කර ඉගෙනීමෙන්", "එක් ප්‍රදේශයක නැටුම් පමණක් උසස් යැයි සැලකීමෙන්", "වෙනත් සංස්කෘතික නැටුම් සම්පූර්ණයෙන් තහනම් කිරීමෙන්", "සියලු ජන නැටුම් විභාගවලින් ඉවත් කිරීමෙන්", "සිංහල, දෙමළ හා අනෙකුත් සංස්කෘතික නැටුම් අධ්‍යයනයෙන් අන්‍යෝන්‍ය ගරුත්වය ඇති වේ."),
        q("ශ්‍රී ලංකාවේ උතුරු හා නැගෙනහිර ප්‍රදේශවල ප්‍රචලිත 'කාවඩි' හා 'කෝලාට්ටම්' නර්තනවලින් ප්‍රකාශ වන ප්‍රධාන ලක්ෂණය කුමක්ද?", "භක්තිය, උත්සවශ්‍රීය සහ සාමූහික තාල රටා", "සංගීතයෙන් තොර නිශ්ශබ්ද භාවනාව", "සත්ව දඩයමේ බියජනක චලන", "රාත්‍රී සන්නි වෙස්මුහුණු රංගනය", "දෙමළ සංස්කෘතියට අයත් මෙම නැටුම් දේව වන්දනාව හා උත්සව ප්‍රීතිය පිළිබිඹු කරයි."),
        q("නව නර්තන නිර්මාණයකදී 'සමබර ඇඳුම් වර්ණ සංයෝජනය' වැදගත් වන්නේ ඇයි?", "පසුතලයෙන් ශිල්පීන් පැහැදිලිව වෙන් වී පෙනී රසය වැඩි වීමට", "ශිල්පීන් පසුබිම් තිරය තුළ නොපෙනී යාමට", "විදුලි පහන් සියල්ල නිවා දැමීමට හැකි වීමට", "ඇඳුම්වල බර ප්‍රමාණය ඉහළ නැංවීමට", "පසුබිම් තිරයේ වර්ණය හා රංග වස්ත්‍ර වර්ණය එකම නොවී මනාව ඉස්මතු විය යුතුය."),
        q("දේශීය නර්තනයේ 'ගමන් පදයක්' හා 'වන්නම් පදයක්' අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "ගමන් පදය පියවර ගමනටත් වන්නම් පදය සත්ව හෝ දේව වර්ණනා නැටීමටත් යොදයි", "ගමන් පදය ඉඳගෙන නටන අතර වන්නම දිව යමින් නැටේ", "ගමන් පදයට තාලයක් නැති අතර වන්නමට බෙර නැත", "දෙකම බටහිර වාද්‍ය භාණ්ඩවලින් පමණක් වයයි", "සරල චලනයන්ගෙන් යුත් ගමන් පද අඩව් හා වන්නම් අතර සම්බන්ධතා ගොඩනඟයි."),
        q("නර්තන විභාගවල 'ප්‍රායෝගික පරීක්ෂණයේදී' සිසුන්ගෙන් මූලිකවම අපේක්ෂා කරන ගුණාංග මොනවාද?", "නිවැරදි මණ්ඩි ඉරියව්ව, තාල පිළිපැදීම, මුද්‍රා හා භාව ප්‍රකාශනය", "ඉතා දිගු රචනා පොත් දෙකක් ලියා භාර දීම", "වේදිකා විදුලි පද්ධති අලුත්වැඩියා කිරීම", "නැටුම් ආභරණ තමන් විසින්ම රනින් නිමවීම", "ප්‍රායෝගික දක්ෂතාව මැනීමේදී ශාරීරික සමබරතාව හා තාල නිරවද්‍යතාව ප්‍රධාන වේ."),
        q("නර්තනය සඳහා 'කායික නම්‍යශීලී බව' (Flexibility) වර්ධනය කර ගැනීමට පුහුණු කළ යුතු හොඳම අභ්‍යාස මොනවාද?", "සන්ධි හා මාංශ පේශි ක්‍රමානුකූලව දිග හැරීමේ ව්‍යායාම (Stretching)", "පැය ගණනක් එකම පුටුවක නොසෙල්වී වාඩි වී සිටීම", "ඉතා බර යකඩ එසවීමේ තරග පමණක් පුහුණු වීම", "කෙටි දුර පිහිනීමකින් තොරව නිදා ගැනීම", "උරහිස්, කොන්ද හා උකුළු සන්ධිවල නම්‍යතාව වර්ධනය කිරීම නර්තන චලන සුමට කරයි."),
        q("දේශීය නර්තන ක්ෂේත්‍රයේ 'වේදිකා පෙරහුරු' (Stage Rehearsal) අවසාන අදියරේදී සිදු කරන 'ඇඳුම් පෙරහුරුව' (Dress Rehearsal) වැදගත් වන්නේ ඇයි?", "පූර්ණ ඇඳුම් හා උපාංග සහිතව චලන පහසුව හා කාලය පරීක්ෂා කිරීමට", "ඇඳුම් සේදීමට අවශ්‍ය වතුර ප්‍රමාණය මැන ගැනීමට", "ප්‍රේක්ෂකයන්ට නොමිලේ ආහාර බෙදා දීමට", "වෙස්මුහුණු කැපීම ආරම්භ කිරීමට", "සැබෑ ප්‍රසංගයේදී ඇඳුම් බර හෝ ආභරණ නිසා සිදුවිය හැකි බාධා කල්තියා හඳුනා ගත හැකිය."),
        q("භාරතීය හා දේශීය නර්තනයේදී 'නෘත්ත, නෘත්‍ය සහ නාට්‍ය' යන ත්‍රිවිධ අංග අතරින් භාව හා රස රහිත හුදු රිද්මයානුකූල පියවර නැටීම හඳුන්වන්නේ කුමන නමකින්ද?", "නෘත්ත (Nritta)", "නෘත්‍ය (Nritya)", "නාට්‍ය (Natya)", "සාත්වික (Satvika)", "කතා අර්ථයක් නොදක්වා තාලයට හා ලයට පමණක් නටන ශුද්ධ නර්තනය 'නෘත්ත' ලෙස හැඳින්වේ."),
        q("අභිනය, හස්ත මුද්‍රා හා භාව ප්‍රකාශනය ඇසුරෙන් කවියක හෝ ගීතයක අර්ථය දැක්වීම හඳුන්වන්නේ කෙසේද?", "නෘත්‍ය (Nritya)", "නෘත්ත (Nritta)", "තාණ්ඩව (Tandava)", "සමපාද (Samapada)", "නෘත්තයට අර්ථවත් අභිනය එක් වූ විට එය 'නෘත්‍ය' නම් ප්‍රකාශන නර්තනය බවට පත්වේ."),
        q("නර්තනය, සංගීතය සහ නාට්‍යමය දෙබස් හෝ චරිත නිරූපණය එක්වී කතා පුවතක් රඟ දැක්වීම හඳුන්වන්නේ කුමන අංගය ලෙසද?", "නාට්‍ය (Natya)", "නෘත්ත (Nritta)", "තිස්‍ර ගතිය", "දෙතිත", "සම්පූර්ණ කතාවක් හා චරිත පද්ධතියක් රංගනයෙන් ඉදිරිපත් කිරීම 'නාට්‍ය' ලෙස විග්‍රහ වේ."),
        q("නර්තන නිර්මාණයකදී 'සරල චලනයක් ක්‍රමයෙන් සංකීර්ණ වීම' මඟින් ප්‍රේක්ෂකයා තුළ ඇතිවන මානසික බලපෑම කුමක්ද?", "කුතුහලය, උද්වේගය හා රසාස්වාදය ක්‍රමානුකූලව වර්ධනය වීම", "ප්‍රේක්ෂකයන්ට නින්ද යාමට පටන් ගැනීම", "නර්තනයේ ආරම්භක තේමාව අමතක වී යාම", "සංගීත වාදනය සම්පූර්ණයෙන් ඇසීම නතර වීම", "ක්‍රමික වර්ධනය මඟින් රංගනය උච්චතම අවස්ථාව වෙත ගෙන යාම කලාත්මක රීතියකි."),
        q("දේශීය නර්තන ක්ෂේත්‍රයට අදාළව 'සංරක්ෂණ කෞතුකාගාර' හා 'ඩිජිටල් ලේඛනාගාර' මඟින් ඉටුවන කාර්යය කුමක්ද?", "පැරණි වෙස්මුහුණු, ඇඳුම්, පුස්කොළ පොත් හා පද අනාගතයට රැක දීම", "සාම්ප්‍රදායික නැටුම් ප්‍රසංග පැවැත්වීම නීතියෙන් තහනම් කිරීම", "වෙස් ඇඳුම් පැළඳීම කෞතුකාගාර සේවකයන්ට පමණක් සීමා කිරීම", "පැරණි බෙර වාදන යන්ත්‍ර මඟින් විනාශ කර දැමීම", "අනාගත පර්යේෂකයන්ට හා සිසුන්ට මූලාශ්‍ර සාක්ෂි සුරක්ෂිතව පවත්වා ගැනීමට එය උපකාරී වේ."),
        q("නර්තන ශිල්පියෙකු ප්‍රසංග අවස්ථාවකදී හදිසියේම තම සගයෙකුට පියවර වැරදුණහොත් කණ්ඩායමක් ලෙස කළ යුත්තේ කුමක්ද?", "අන් අය සංයමයෙන් රංගනය දිගටම ගෙන යමින් ඔහුට යළි එක්වීමට ඉඩ සැලසීම", "වේදිකාව මැද නැටුම නවතා වැරදුණු අය දෙසට ඇඟිල්ල දිගු කිරීම", "මුළු කණ්ඩායමම ප්‍රේක්ෂකයන් ඉදිරියේ බිම වාඩි වීම", "බෙර වාදකයාට කතා කර මුල සිට පටන් ගැනීමට බල කිරීම", "කණ්ඩායම් හැඟීම හා වෘත්තීය විනය මඟින් කුඩා අඩුපාඩු ප්‍රේක්ෂකයාට නොදැනෙන සේ සමනය කළ හැකිය."),
        q("නර්තනය 'සමස්ත පෞරුෂ සංවර්ධනයට' උපකාරී වන ප්‍රධාන ආකාරය කුමක්ද?", "ශාරීරික ශක්තිය, නිර්මාණශීලී මනස හා සමාජීය ආත්ම විශ්වාසය එක්ව වැඩීම", "පොත්පත් කියවීම සම්පූර්ණයෙන් නතර කර ගැනීමට උදව් වීම", "අන් අය සමඟ කතා කිරීමෙන් වැළකී සිටීමට හුරු කිරීම", "විවේචන කිසිවක් නොපිළිගන්නා අහංකාර සිතුවිලි ඇති කිරීම", "සෞන්දර්ය ක්‍රියාකාරකමක් ලෙස නර්තනය කය, මනස හා හදවත යන තුනම සමබරව ඔප් නංවයි."),
        q("අ.පො.ස. සාමාන්‍ය පෙළ නර්තන විෂයය හැදෑරීමෙන් සිසුවෙකු තුළ ගොඩනැගෙන උසස්ම ජාතික ආකල්පය කුමක්ද?", "තම මව්බිමේ සාම්ප්‍රදායික කලා උරුමය අගය කරමින් ආරක්ෂා කිරීමේ හැඟීම", "විදේශීය සංස්කෘතීන් පමණක් උසස් යැයි පිළිගැනීමේ මානසිකත්වය", "පැරණි ගැමි කලා අංග නූතන ලෝකයට නොගැළපෙන බව සිතීම", "සංස්කෘතික චාරිත්‍ර වාරිත්‍ර හුදු මිථ්‍යාවන් ලෙස බැහැර කිරීම", "දේශීය කලා සම්ප්‍රදාය පිළිබඳ නිවැරදි අවබෝධය රටේ අනන්‍යතාව රකින පුරවැසියන් බිහි කරයි."),
        q("නර්තනයේ රිද්මය, තාලය, නිර්මාණශීලීත්වය හා සම්ප්‍රදායික විනය එක් වූ විට බිහිවන කලා නිර්මාණය හඳුන්වන්නේ කෙසේද?", "පරිපූර්ණ සෞන්දර්යාත්මක රංග කලා කෘතියක් ලෙස", "හුදු කායික වේගවත් තරග අභ්‍යාසයක් ලෙස", "වාද්‍ය භාණ්ඩ ප්‍රදර්ශන මණ්ඩපයක් ලෙස", "පිටු ගණනක් දිග කවි පොත් එකතුවක් ලෙස", "නර්තනයේ න්‍යාය, ප්‍රායෝගික හුරුව හා රස නිෂ්පත්තිය සමබරව මුසු වීම උසස් කලාවක ලක්ෂණයයි.")
    )
}
